"% model.m - Closed-loop step-response metrics

% System matrices
A_cl = [-0.55, 1.0; -3.9, -1.3];
B_cl = [0.0; 1.0];
C_cl = [1.0, 0.0];

% Simulation parameters
dt = 0.01;
T = 30;
t = 0:dt:T;
N = length(t);

% Exact zero-order-hold discretization
Ad = expm(A_cl * dt);
Bd = A_cl \ ((Ad - eye(2)) * B_cl);

% DC value (steady-state for unit step)
y_inf = -C_cl * (A_cl \ B_cl);

% Simulate step response with u = 1 for all steps
x = zeros(2, 1);
y = zeros(1, N);
y(1) = C_cl * x;  % y at t=0
for k = 1:N-1
    x = Ad * x + Bd * 1.0;
    y(k+1) = C_cl * x;
end

% Rise time: first 10% to first 90% crossing of y_inf with linear interpolation
thresh_10 = 0.1 * y_inf;
thresh_90 = 0.9 * y_inf;

t_10 = NaN;
t_90 = NaN;

for k = 1:N-1
    if isnan(t_10) && y(k) <= thresh_10 && y(k+1) >= thresh_10
        t_10 = t(k) + (thresh_10 - y(k)) / (y(k+1) - y(k)) * dt;
    end
    if isnan(t_90) && y(k) <= thresh_90 && y(k+1) >= thresh_90
        t_90 = t(k) + (thresh_90 - y(k)) / (y(k+1) - y(k)) * dt;
    end
end

rise_time_s = t_90 - t_10;

% Percent overshoot
max_y = max(y);
overshoot_pct = (max_y - y_inf) / abs(y_inf) * 100;

% 2% settling time: time of last grid sample outside the 2% band
settling_tol = 0.02 * abs(y_inf);
outside = abs(y - y_inf) > settling_tol;
last_outside_idx = find(outside, 1, 'last');
if isempty(last_outside_idx)
    settling_time_s = 0;
else
    settling_time_s = t(last_outside_idx);
end

% Write result.json
result = struct();
result.rise_time_s = rise_time_s;
result.overshoot_pct = overshoot_pct;
result.settling_time_s = settling_time_s;

json_str = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_str);
fclose(fid);"
